// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title Guestbook — BOT Launchpad template #1
/// @notice Anyone can sign once with a short message.
contract Guestbook {
    struct Entry {
        address signer;
        uint64 at;
        string message;
    }

    /// @notice Template identifier used by the Launchpad registry.
    uint8 public constant TEMPLATE_ID = 1;
    /// @notice Maximum title length in bytes.
    uint256 public constant MAX_NAME = 64;
    /// @notice Maximum message length in bytes.
    uint256 public constant MAX_MESSAGE = 140;

    /// @notice The wallet that deployed this guestbook.
    address public owner;
    /// @notice Guestbook title.
    string public name;
    /// @notice Whether a wallet has already signed.
    mapping(address => bool) public hasSigned;

    Entry[] private _entries;

    /// @notice Emitted when a wallet signs the guestbook.
    event Signed(uint256 indexed id, address indexed signer);

    error EmptyText();
    error TextTooLong(uint256 max);
    error AlreadySigned();

    /// @param name_ Guestbook title, 1–64 bytes.
    constructor(string memory name_) {
        _checkText(name_, MAX_NAME);
        owner = msg.sender;
        name = name_;
    }

    /// @notice Sign the guestbook. One signature per wallet.
    /// @param message 1–140 bytes.
    function sign(string calldata message) external {
        if (hasSigned[msg.sender]) revert AlreadySigned();
        _checkText(message, MAX_MESSAGE);
        hasSigned[msg.sender] = true;
        _entries.push(Entry(msg.sender, uint64(block.timestamp), message));
        emit Signed(_entries.length - 1, msg.sender);
    }

    /// @notice Number of entries.
    function entryCount() external view returns (uint256) {
        return _entries.length;
    }

    /// @notice Page through entries in insertion order.
    /// @param from First index. Returns an empty array when out of range.
    /// @param count Maximum number of entries to return.
    function getEntries(uint256 from, uint256 count) external view returns (Entry[] memory page) {
        uint256 len = _entries.length;
        if (from >= len) return page;
        uint256 end = len - from < count ? len : from + count;
        page = new Entry[](end - from);
        for (uint256 i = from; i < end; i++) page[i - from] = _entries[i];
    }

    function _checkText(string memory s, uint256 max) private pure {
        uint256 n = bytes(s).length;
        if (n == 0) revert EmptyText();
        if (n > max) revert TextTooLong(max);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title Poll — BOT Launchpad template #2
/// @notice One vote per wallet until the end time or until the owner closes it.
contract Poll {
    /// @notice Template identifier used by the Launchpad registry.
    uint8 public constant TEMPLATE_ID = 2;
    /// @notice Maximum question length in bytes.
    uint256 public constant MAX_NAME = 120;
    /// @notice Maximum option label length in bytes.
    uint256 public constant MAX_OPTION = 48;
    /// @notice Minimum number of options.
    uint256 public constant MIN_OPTIONS = 2;
    /// @notice Maximum number of options.
    uint256 public constant MAX_OPTIONS = 6;

    /// @notice The wallet that deployed this poll.
    address public owner;
    /// @notice The poll question.
    string public name;
    /// @notice Unix time after which voting stops.
    uint64 public endsAt;
    /// @notice True once the owner closes the poll early.
    bool public closed;
    /// @notice Whether a wallet has voted.
    mapping(address => bool) public hasVoted;

    string[] private _options;
    uint256[] private _votes;
    uint256 private _total;

    /// @notice Emitted on every vote.
    event Voted(address indexed voter, uint8 indexed option);
    /// @notice Emitted when the owner closes the poll.
    event Closed(address indexed by);

    error EmptyText();
    error TextTooLong(uint256 max);
    error BadOptions();
    error EndInPast();
    error PollClosed();
    error AlreadyVoted();
    error InvalidOption();
    error NotOwner();

    /// @param question 1–120 bytes.
    /// @param options_ 2–6 labels of 1–48 bytes each.
    /// @param endsAt_ Unix time in the future.
    constructor(string memory question, string[] memory options_, uint64 endsAt_) {
        _checkText(question, MAX_NAME);
        uint256 n = options_.length;
        if (n < MIN_OPTIONS || n > MAX_OPTIONS) revert BadOptions();
        for (uint256 i = 0; i < n; i++) _checkText(options_[i], MAX_OPTION);
        if (endsAt_ <= block.timestamp) revert EndInPast();

        owner = msg.sender;
        name = question;
        endsAt = endsAt_;
        _options = options_;
        _votes = new uint256[](n);
    }

    /// @notice Cast one vote.
    /// @param option Index into `getOptions()`.
    function vote(uint8 option) external {
        if (!isOpen()) revert PollClosed();
        if (hasVoted[msg.sender]) revert AlreadyVoted();
        if (option >= _options.length) revert InvalidOption();
        hasVoted[msg.sender] = true;
        _votes[option] += 1;
        _total += 1;
        emit Voted(msg.sender, option);
    }

    /// @notice Close the poll before its end time. Owner only.
    function close() external {
        if (msg.sender != owner) revert NotOwner();
        if (!isOpen()) revert PollClosed();
        closed = true;
        emit Closed(msg.sender);
    }

    /// @notice True while votes are accepted.
    function isOpen() public view returns (bool) {
        return !closed && block.timestamp < endsAt;
    }

    /// @notice Option labels in index order.
    function getOptions() external view returns (string[] memory) {
        return _options;
    }

    /// @notice Vote counts in option order.
    function results() external view returns (uint256[] memory) {
        return _votes;
    }

    /// @notice Total votes cast.
    function totalVotes() external view returns (uint256) {
        return _total;
    }

    function _checkText(string memory s, uint256 max) private pure {
        uint256 n = bytes(s).length;
        if (n == 0) revert EmptyText();
        if (n > max) revert TextTooLong(max);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title To-do Board — BOT Launchpad template #3
/// @notice A shared task list. The owner decides whether anyone can add tasks.
contract TodoBoard {
    struct Task {
        address creator;
        bool done;
        uint64 at;
        string text;
    }

    /// @notice Template identifier used by the Launchpad registry.
    uint8 public constant TEMPLATE_ID = 3;
    /// @notice Maximum board name length in bytes.
    uint256 public constant MAX_NAME = 64;
    /// @notice Maximum task length in bytes.
    uint256 public constant MAX_TASK = 120;

    /// @notice The wallet that deployed this board.
    address public owner;
    /// @notice Board name.
    string public name;
    /// @notice When true, any wallet can add tasks. Otherwise only the owner can.
    bool public openToAll;

    Task[] private _tasks;

    /// @notice Emitted when a task is added.
    event TaskAdded(uint256 indexed id, address indexed creator);
    /// @notice Emitted when a task is marked done or not done.
    event TaskToggled(uint256 indexed id, address indexed by, bool done);

    error EmptyText();
    error TextTooLong(uint256 max);
    error NotAllowed();
    error NoSuchTask();

    /// @param name_ Board name, 1–64 bytes.
    /// @param openToAll_ Whether any wallet can add tasks.
    constructor(string memory name_, bool openToAll_) {
        _checkText(name_, MAX_NAME);
        owner = msg.sender;
        name = name_;
        openToAll = openToAll_;
    }

    /// @notice Add a task.
    /// @param text 1–120 bytes.
    function addTask(string calldata text) external {
        if (!openToAll && msg.sender != owner) revert NotAllowed();
        _checkText(text, MAX_TASK);
        _tasks.push(Task(msg.sender, false, uint64(block.timestamp), text));
        emit TaskAdded(_tasks.length - 1, msg.sender);
    }

    /// @notice Flip a task between done and not done. Owner or task creator only.
    function toggle(uint256 id) external {
        if (id >= _tasks.length) revert NoSuchTask();
        Task storage t = _tasks[id];
        if (msg.sender != owner && msg.sender != t.creator) revert NotAllowed();
        t.done = !t.done;
        emit TaskToggled(id, msg.sender, t.done);
    }

    /// @notice Number of tasks.
    function taskCount() external view returns (uint256) {
        return _tasks.length;
    }

    /// @notice Page through tasks in insertion order.
    function getTasks(uint256 from, uint256 count) external view returns (Task[] memory page) {
        uint256 len = _tasks.length;
        if (from >= len) return page;
        uint256 end = len - from < count ? len : from + count;
        page = new Task[](end - from);
        for (uint256 i = from; i < end; i++) page[i - from] = _tasks[i];
    }

    function _checkText(string memory s, uint256 max) private pure {
        uint256 n = bytes(s).length;
        if (n == 0) revert EmptyText();
        if (n > max) revert TextTooLong(max);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title Tip Jar — BOT Launchpad template #4
/// @notice Collect BOT tips with short notes. Only the owner can withdraw.
/// @dev No receive/fallback: plain transfers revert, so every tip goes through `tip`.
contract TipJar {
    struct Tip {
        address from;
        uint256 amount;
        uint64 at;
        string note;
    }

    /// @notice Template identifier used by the Launchpad registry.
    uint8 public constant TEMPLATE_ID = 4;
    /// @notice Maximum name length in bytes.
    uint256 public constant MAX_NAME = 64;
    /// @notice Maximum thank-you message and note length in bytes.
    uint256 public constant MAX_NOTE = 140;
    /// @notice Smallest accepted tip.
    uint256 public constant MIN_TIP = 0.001 ether;

    /// @notice The wallet that deployed this jar and receives withdrawals.
    address public owner;
    /// @notice Jar name.
    string public name;
    /// @notice Message shown to tippers.
    string public thankYou;
    /// @notice Sum of all tips ever received.
    uint256 public totalTipped;

    Tip[] private _tips;

    /// @notice Emitted on every tip.
    event Tipped(uint256 indexed id, address indexed from, uint256 amount);
    /// @notice Emitted when the owner withdraws.
    event Withdrawn(address indexed to, uint256 amount);

    error EmptyText();
    error TextTooLong(uint256 max);
    error TipTooSmall(uint256 min);
    error NotOwner();
    error NothingToWithdraw();
    error TransferFailed();

    /// @param name_ Jar name, 1–64 bytes.
    /// @param thankYou_ Thank-you message, 0–140 bytes.
    constructor(string memory name_, string memory thankYou_) {
        uint256 n = bytes(name_).length;
        if (n == 0) revert EmptyText();
        if (n > MAX_NAME) revert TextTooLong(MAX_NAME);
        if (bytes(thankYou_).length > MAX_NOTE) revert TextTooLong(MAX_NOTE);
        owner = msg.sender;
        name = name_;
        thankYou = thankYou_;
    }

    /// @notice Send a tip of at least `MIN_TIP`.
    /// @param note Optional note, 0–140 bytes.
    function tip(string calldata note) external payable {
        if (msg.value < MIN_TIP) revert TipTooSmall(MIN_TIP);
        if (bytes(note).length > MAX_NOTE) revert TextTooLong(MAX_NOTE);
        totalTipped += msg.value;
        _tips.push(Tip(msg.sender, msg.value, uint64(block.timestamp), note));
        emit Tipped(_tips.length - 1, msg.sender, msg.value);
    }

    /// @notice Send the whole balance to the owner. Owner only.
    function withdraw() external {
        if (msg.sender != owner) revert NotOwner();
        uint256 amount = address(this).balance;
        if (amount == 0) revert NothingToWithdraw();
        emit Withdrawn(msg.sender, amount);
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert TransferFailed();
    }

    /// @notice Current balance waiting to be withdrawn.
    function balance() external view returns (uint256) {
        return address(this).balance;
    }

    /// @notice Number of tips.
    function tipCount() external view returns (uint256) {
        return _tips.length;
    }

    /// @notice Page through tips in insertion order.
    function getTips(uint256 from, uint256 count) external view returns (Tip[] memory page) {
        uint256 len = _tips.length;
        if (from >= len) return page;
        uint256 end = len - from < count ? len : from + count;
        page = new Tip[](end - from);
        for (uint256 i = from; i < end; i++) page[i - from] = _tips[i];
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title Event Check-in — BOT Launchpad template #5
/// @notice Proof of attendance: one check-in per wallet inside a time window, up to a cap.
contract EventCheckIn {
    struct Attendee {
        address who;
        uint64 at;
    }

    /// @notice Template identifier used by the Launchpad registry.
    uint8 public constant TEMPLATE_ID = 5;
    /// @notice Maximum event name length in bytes.
    uint256 public constant MAX_NAME = 64;
    /// @notice Largest allowed attendee cap.
    uint32 public constant MAX_CAP = 10_000;

    /// @notice The wallet that deployed this check-in.
    address public owner;
    /// @notice Event name.
    string public name;
    /// @notice Check-in opens at this unix time.
    uint64 public startsAt;
    /// @notice Check-in closes at this unix time (exclusive).
    uint64 public endsAt;
    /// @notice Attendee cap.
    uint32 public maxAttendees;
    /// @notice Whether a wallet has checked in.
    mapping(address => bool) public checkedIn;

    Attendee[] private _list;

    /// @notice Emitted on every check-in. `n` is the zero-based attendee index.
    event CheckedIn(uint256 indexed n, address indexed who);

    error EmptyText();
    error TextTooLong(uint256 max);
    error BadWindow();
    error BadMax();
    error NotStarted();
    error Ended();
    error Full();
    error AlreadyCheckedIn();

    /// @param name_ Event name, 1–64 bytes.
    /// @param startsAt_ Opening time.
    /// @param endsAt_ Closing time, after `startsAt_` and in the future.
    /// @param maxAttendees_ 1–10,000.
    constructor(string memory name_, uint64 startsAt_, uint64 endsAt_, uint32 maxAttendees_) {
        uint256 n = bytes(name_).length;
        if (n == 0) revert EmptyText();
        if (n > MAX_NAME) revert TextTooLong(MAX_NAME);
        if (startsAt_ >= endsAt_ || endsAt_ <= block.timestamp) revert BadWindow();
        if (maxAttendees_ == 0 || maxAttendees_ > MAX_CAP) revert BadMax();
        owner = msg.sender;
        name = name_;
        startsAt = startsAt_;
        endsAt = endsAt_;
        maxAttendees = maxAttendees_;
    }

    /// @notice Check in once while the window is open and the cap is not reached.
    function checkIn() external {
        if (block.timestamp < startsAt) revert NotStarted();
        if (block.timestamp >= endsAt) revert Ended();
        if (checkedIn[msg.sender]) revert AlreadyCheckedIn();
        if (_list.length >= maxAttendees) revert Full();
        checkedIn[msg.sender] = true;
        _list.push(Attendee(msg.sender, uint64(block.timestamp)));
        emit CheckedIn(_list.length - 1, msg.sender);
    }

    /// @notice Number of attendees.
    function count() external view returns (uint256) {
        return _list.length;
    }

    /// @notice Window state, attendee count and cap in one call.
    function status() external view returns (bool open, uint256 attendeeCount, uint32 max) {
        attendeeCount = _list.length;
        open = block.timestamp >= startsAt && block.timestamp < endsAt && attendeeCount < maxAttendees;
        max = maxAttendees;
    }

    /// @notice Page through attendees in check-in order.
    function attendees(uint256 from, uint256 count_) external view returns (Attendee[] memory page) {
        uint256 len = _list.length;
        if (from >= len) return page;
        uint256 end = len - from < count_ ? len : from + count_;
        page = new Attendee[](end - from);
        for (uint256 i = from; i < end; i++) page[i - from] = _list[i];
    }
}
